import heapq

E = {('A','B'):1, ('A','C'):100, ('B','C'):1, ('B','D'):100, ('C','D'):1}
G = {}
for (u, v), c in E.items():                     # 무향 그래프: 양방향 같은 비용
    G.setdefault(u, []).append((v, c)); G.setdefault(v, []).append((u, c))

def ucs(start, is_end, succ):
    frontier = [(0, start)]                     # (우선순위, 상태)
    best, back, explored = {start: 0}, {}, []
    while frontier:
        p, s = heapq.heappop(frontier)
        if s in explored or p > best[s]:        # 낡은 항목은 버린다(지연 삭제)
            continue
        explored.append(s)
        print(f"pop {s} past_cost={p}")
        if is_end(s):
            path = [s]
            while path[-1] != start: path.append(back[path[-1]])
            return p, path[::-1], explored
        for t, c in succ(s):
            if t not in explored and p + c < best.get(t, float('inf')):
                best[t], back[t] = p + c, s       # 더 싼 길을 찾으면 갱신
                heapq.heappush(frontier, (p + c, t))
    return None

print(ucs('A', lambda s: s == 'D', lambda s: G[s]))
